import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <cuda_runtime.h>
#include <torch/extension.h>

#define BLOCK_M 64
#define BLOCK_N 64
#define THREAD_TM 4
#define THREAD_TN 4
#define MAX_K 32
// Optimized for tall-skinny GEMM where K is small (<= MAX_K) and M, N are large.
// Threadblock tiles over the large M/N output dimensions, keeps the small K
// dimension fully resident in shared memory/registers (unrolled), and each
// thread computes a THREAD_TM x THREAD_TN register-blocked output tile,
// writing results back with vectorized float4 stores when possible.
__global__ void matmul_kernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float* __restrict__ C,
                               int M, int K, int N) {
    __shared__ float As[BLOCK_M][MAX_K];
    __shared__ float Bs[MAX_K][BLOCK_N];
    int blockRow = blockIdx.y * BLOCK_M;
    int blockCol = blockIdx.x * BLOCK_N;
    int tx = threadIdx.x; // 0..15
    int ty = threadIdx.y; // 0..15
    int tid = ty * blockDim.x + tx; // 0..255
    int numThreads = blockDim.x * blockDim.y;
    // Cooperative load of A tile (BLOCK_M x K) into shared memory, zero-padded.
    for (int i = tid; i < BLOCK_M * MAX_K; i += numThreads) {
        int r = i / MAX_K;
        int c = i % MAX_K;
        int gRow = blockRow + r;
        As[r][c] = (gRow < M && c < K) ? A[gRow * K + c] : 0.0f;
    }
    // Cooperative load of B tile (K x BLOCK_N) into shared memory, zero-padded.
    for (int i = tid; i < MAX_K * BLOCK_N; i += numThreads) {
        int r = i / BLOCK_N;
        int c = i % BLOCK_N;
        int gCol = blockCol + c;
        Bs[r][c] = (r < K && gCol < N) ? B[r * N + gCol] : 0.0f;
    }
    __syncthreads();
    float acc[THREAD_TM][THREAD_TN];
    #pragma unroll
    for (int i = 0; i < THREAD_TM; ++i) {
        #pragma unroll
        for (int j = 0; j < THREAD_TN; ++j) {
            acc[i][j] = 0.0f;
        }
    }
    #pragma unroll
    for (int k = 0; k < MAX_K; ++k) {
        float aFrag[THREAD_TM];
        #pragma unroll
        for (int i = 0; i < THREAD_TM; ++i) {
            aFrag[i] = As[ty * THREAD_TM + i][k];
        }
        float bFrag[THREAD_TN];
        #pragma unroll
        for (int j = 0; j < THREAD_TN; ++j) {
            bFrag[j] = Bs[k][tx * THREAD_TN + j];
        }
        #pragma unroll
        for (int i = 0; i < THREAD_TM; ++i) {
            #pragma unroll
            for (int j = 0; j < THREAD_TN; ++j) {
                acc[i][j] += aFrag[i] * bFrag[j];
            }
        }
    }
    #pragma unroll
    for (int i = 0; i < THREAD_TM; ++i) {
        int gRow = blockRow + ty * THREAD_TM + i;
        if (gRow < M) {
            int gColBase = blockCol + tx * THREAD_TN;
            if (gColBase + THREAD_TN <= N) {
                float4 val = make_float4(acc[i][0], acc[i][1], acc[i][2], acc[i][3]);
                *reinterpret_cast<float4*>(&C[gRow * N + gColBase]) = val;
            } else {
                #pragma unroll
                for (int j = 0; j < THREAD_TN; ++j) {
                    int gCol = gColBase + j;
                    if (gCol < N) {
                        C[gRow * N + gCol] = acc[i][j];
                    }
                }
            }
        }
    }
}
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    A = A.contiguous();
    B = B.contiguous();
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);
    auto C = torch::empty({M, N}, A.options());
    dim3 block(BLOCK_N / THREAD_TN, BLOCK_M / THREAD_TM);
    dim3 grid((N + BLOCK_N - 1) / BLOCK_N, (M + BLOCK_M - 1) / BLOCK_M);
    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K, N
    );
    return C;
}
"""

cpp_source = r"""
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

matmul_module = load_inline(
    name="matmul_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a single matrix multiplication (C = A * B)
    using a custom CUDA tiled GEMM kernel, tailored for the tall-skinny
    matrix multiplication pattern (small inner dimension K).
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul = matmul_module

    def forward(self, A, B):
        A = A.cuda().float()
        B = B.cuda().float()
        return self.matmul.matmul_cuda(A, B)


M = 16384 * 2
N = 16 * 2

def get_inputs():
    A = torch.rand(M, N)
    B = torch.rand(N, M)
    return [A, B]

def get_init_inputs():
    return []

